const scenes=html=>html.match(/<section\b[^]*?<\/section>/g);
const textTween=html=>html.match(/beats.forEach\([^]*?const blueBeat/)[0];
const preservation={sceneHtmlByteIdentical:JSON.stringify(scenes(oldHtml))===JSON.stringify(scenes(newHtml)),textAnimationByteIdentical:textTween(oldHtml)===textTween(newHtml)};
const browser=await chromium.launch({headless:true});
const page=await browser.newPage({viewport:{width:1280,height:720}});
await page.goto('file://'+path.resolve(`${base}/project/index.html`));await page.evaluate(()=>document.fonts.ready);
