 const tl=window.__timelines['saas-demo'];let samples=0;const failures=[];
 const elements=[...document.querySelectorAll('.media-original,.media-shell')];
 for(const el of elements){
  const start=Number(el.dataset.start);const read=()=>{const b=el.getBoundingClientRect(),c=getComputedStyle(el);return {rect:[b.x,b.y,b.width,b.height],transform:c.transform,opacity:Number(c.opacity)}};
  tl.seek(start+.6,false);const expected=read();let prior=-1;
  for(const offset of [0,.033333,.066667,.1,.2,.28,.6]){
   tl.seek(start+offset,false);samples++;const actual=read();
   if(JSON.stringify(actual.rect)!==JSON.stringify(expected.rect)||actual.transform!=='none'||actual.opacity<prior-.00001)failures.push({id:el.id,offset,actual,expected,prior});
