});await browser.close();
const result={preservation,mediaMotion,passed:Object.values(preservation).every(Boolean)&&mediaMotion.passed};
await fs.writeFile(`${base}/source-motion-check.json`,JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result,null,2));if(!result.passed)process.exitCode=1;
